import{_ as n,o as e,c as i,a5 as a}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"04. Đặc Tả Giao Diện & Trải Nghiệm Người Dùng (UI/UX & Screen Specification)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/personal-agency-transition/04_UI_UX_AND_SCREEN_SPEC.md","filePath":"feature/agency-workspace/personal-agency-transition/04_UI_UX_AND_SCREEN_SPEC.md"}'),o={name:"feature/agency-workspace/personal-agency-transition/04_UI_UX_AND_SCREEN_SPEC.md"};function h(l,t,c,r,g,s){return e(),i("div",null,[...t[0]||(t[0]=[a(`<h1 id="_04-đac-ta-giao-dien-trai-nghiem-nguoi-dung-ui-ux-screen-specification" tabindex="-1">04. Đặc Tả Giao Diện &amp; Trải Nghiệm Người Dùng (UI/UX &amp; Screen Specification) <a class="header-anchor" href="#_04-đac-ta-giao-dien-trai-nghiem-nguoi-dung-ui-ux-screen-specification" aria-label="Permalink to &quot;04. Đặc Tả Giao Diện &amp; Trải Nghiệm Người Dùng (UI/UX &amp; Screen Specification)&quot;">​</a></h1><h2 id="_1-man-hinh-tao-agency-moi-agency-create" tabindex="-1">1. Màn Hình Tạo Agency Mới (<code>/agency/create</code>) <a class="header-anchor" href="#_1-man-hinh-tao-agency-moi-agency-create" aria-label="Permalink to &quot;1. Màn Hình Tạo Agency Mới (\`/agency/create\`)&quot;">​</a></h2><h3 id="_1-1-khoi-chon-muc-đich-su-dung-purpose-selection-cards" tabindex="-1">1.1. Khối Chọn Mục Đích Sử Dụng (Purpose Selection Cards) <a class="header-anchor" href="#_1-1-khoi-chon-muc-đich-su-dung-purpose-selection-cards" aria-label="Permalink to &quot;1.1. Khối Chọn Mục Đích Sử Dụng (Purpose Selection Cards)&quot;">​</a></h3><p>Ngay ở đầu trang tạo Agency, hiển thị 2 thẻ lựa chọn trực quan (Radio Cards) có kèm biểu tượng và mô tả rõ ràng:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌───────────────────────────────────────────────┬───────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  👤 SỬ DỤNG CHO CÁ NHÂN (Khuyên dùng)         │  🏢 SỬ DỤNG CHO DOANH NGHIỆP / AGENCY         │</span></span>
<span class="line"><span>│                                               │                                               │</span></span>
<span class="line"><span>│  Dành cho Solo Creator, Freelancer, KOC       │  Dành cho Media Agency, Marketing Team        │</span></span>
<span class="line"><span>│  • Tự sáng tạo và đăng bài cho kênh của bạn   │  • Quản lý nhiều khách hàng (Clients)         │</span></span>
<span class="line"><span>│  • Không cần quy trình duyệt bài khách hàng   │  • Phân quyền thành viên (Manager, Creator)   │</span></span>
<span class="line"><span>│  • Sẵn sàng làm việc ngay sau khi tạo         │  • Cổng duyệt bài riêng cho khách hàng        │</span></span>
<span class="line"><span>└───────────────────────────────────────────────┴───────────────────────────────────────────────┘</span></span></code></pre></div><h3 id="_1-2-hanh-vi-đong-cua-form-dynamic-form-behavior" tabindex="-1">1.2. Hành vi Động của Form (Dynamic Form Behavior) <a class="header-anchor" href="#_1-2-hanh-vi-đong-cua-form-dynamic-form-behavior" aria-label="Permalink to &quot;1.2. Hành vi Động của Form (Dynamic Form Behavior)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Trường thông tin</th><th style="text-align:left;">Khi chọn &quot;Cá nhân&quot; (<code>PERSONAL</code>)</th><th style="text-align:left;">Khi chọn &quot;Doanh nghiệp&quot; (<code>BUSINESS</code>)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Tiêu đề trường Tên</strong></td><td style="text-align:left;"><em>&quot;Tên thương hiệu / Kênh của bạn&quot;</em> (Gợi ý: Trí Nguyễn Tech, Bếp Nhà Mai...)</td><td style="text-align:left;"><em>&quot;Tên Agency / Công ty truyền thông&quot;</em></td></tr><tr><td style="text-align:left;"><strong>Quy mô nhân sự (Company Size)</strong></td><td style="text-align:left;"><strong>Ẩn</strong> (Hệ thống tự gán mặc định là 1-10 người)</td><td style="text-align:left;"><strong>Hiển thị</strong> (1-10, 11-50, 51-200, 201-500...)</td></tr><tr><td style="text-align:left;"><strong>Lĩnh vực hoạt động (Category)</strong></td><td style="text-align:left;">Hiển thị (Marketing, F&amp;B, Thời trang, Công nghệ, Khác...)</td><td style="text-align:left;">Hiển thị</td></tr><tr><td style="text-align:left;"><strong>Website &amp; Số điện thoại</strong></td><td style="text-align:left;">Hiển thị (Tùy chọn)</td><td style="text-align:left;">Hiển thị (Tùy chọn)</td></tr><tr><td style="text-align:left;"><strong>Màu sắc &amp; Nhận diện (Logo/Banner)</strong></td><td style="text-align:left;">Giữ nguyên bộ chọn Icon / Preset Banner / Upload ảnh</td><td style="text-align:left;">Giữ nguyên</td></tr><tr><td style="text-align:left;"><strong>Mạng xã hội kết nối</strong></td><td style="text-align:left;">Liên kết Fanpage / TikTok / Instagram cá nhân</td><td style="text-align:left;">Liên kết kênh công ty</td></tr><tr><td style="text-align:left;"><strong>Nút bấm Submit</strong></td><td style="text-align:left;"><strong>&quot;Bắt đầu sáng tạo ngay ✨&quot;</strong></td><td style="text-align:left;"><strong>&quot;Tạo Agency&quot;</strong></td></tr></tbody></table><hr><h2 id="_2-trai-nghiem-chuyen-đoi-tuc-thi-instant-transition" tabindex="-1">2. Trải Nghiệm Chuyển Đổi Tức Thì (Instant Transition) <a class="header-anchor" href="#_2-trai-nghiem-chuyen-đoi-tuc-thi-instant-transition" aria-label="Permalink to &quot;2. Trải Nghiệm Chuyển Đổi Tức Thì (Instant Transition)&quot;">​</a></h2><p>Khi người dùng nhấn <strong>&quot;Bắt đầu sáng tạo ngay&quot;</strong>:</p><ol><li>Nút hiển thị trạng thái loading spinner: <em>&quot;Đang khởi tạo không gian làm việc cá nhân của bạn...&quot;</em></li><li>Sau khi API trả về kết quả thành công: <ul><li>Hiển thị Toast thông báo: <em>&quot;Chào mừng bạn! Không gian làm việc cá nhân đã sẵn sàng.&quot;</em></li><li>Tự động nạp <code>defaultWorkspaceId</code> vào <code>useWorkspaceStore</code>.</li><li>Điều hướng lập tức tới: <ul><li><strong>Màn hình mặc định</strong>: <code>/workspaces/{defaultWorkspaceId}/dashboard</code></li><li>(Hoặc nếu người dùng muốn viết bài ngay, có thể cung cấp nút tắt dẫn thẳng tới <code>/workspaces/{defaultWorkspaceId}/content-writing</code>).</li></ul></li></ul></li></ol><hr><h2 id="_3-toi-uu-hoa-sidebar-cho-che-đo-ca-nhan-personal-mode-sidebar" tabindex="-1">3. Tối Ưu Hóa Sidebar Cho Chế Độ Cá Nhân (Personal Mode Sidebar) <a class="header-anchor" href="#_3-toi-uu-hoa-sidebar-cho-che-đo-ca-nhan-personal-mode-sidebar" aria-label="Permalink to &quot;3. Tối Ưu Hóa Sidebar Cho Chế Độ Cá Nhân (Personal Mode Sidebar)&quot;">​</a></h2><h3 id="_3-1-cac-muc-menu-bi-an-khi-o-agency-ca-nhan" tabindex="-1">3.1. Các mục Menu bị ẨN khi ở Agency Cá nhân <a class="header-anchor" href="#_3-1-cac-muc-menu-bi-an-khi-o-agency-ca-nhan" aria-label="Permalink to &quot;3.1. Các mục Menu bị ẨN khi ở Agency Cá nhân&quot;">​</a></h3><p>Để tránh gây rối mắt và loại bỏ các nghiệp vụ B2B không cần thiết, khi <code>currentAgency.type === &#39;PERSONAL&#39;</code>, hệ thống tự động ẩn các mục sau:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Nhóm Menu</th><th style="text-align:left;">Đường dẫn (Route)</th><th style="text-align:left;">Lý do ẩn trong chế độ Cá nhân</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Quản lý Khách hàng</strong></td><td style="text-align:left;"><code>/clients</code>, <code>/clients/create</code>, <code>/clients/:id</code></td><td style="text-align:left;">Cá nhân không quản lý khách hàng bên ngoài.</td></tr><tr><td style="text-align:left;"><strong>Hồ sơ Khách hàng</strong></td><td style="text-align:left;"><code>/client-profiles</code></td><td style="text-align:left;">Cá nhân tự làm chủ thương hiệu của mình.</td></tr><tr><td style="text-align:left;"><strong>Lời mời Khách hàng</strong></td><td style="text-align:left;"><code>/client/invitations</code></td><td style="text-align:left;">Không có lời mời khách hàng.</td></tr><tr><td style="text-align:left;"><strong>Cổng Khách hàng</strong></td><td style="text-align:left;"><code>/portal</code></td><td style="text-align:left;">Không cần cổng giao tiếp với khách hàng.</td></tr><tr><td style="text-align:left;"><strong>Phân quyền Agency</strong></td><td style="text-align:left;"><code>/agency/:id/roles</code></td><td style="text-align:left;">Chỉ có 1 người duy nhất, không cần phân quyền vai trò.</td></tr><tr><td style="text-align:left;"><strong>Thành viên Workspace</strong></td><td style="text-align:left;"><code>/workspaces/:id/members</code></td><td style="text-align:left;">Ẩn mục quản lý phân quyền thành viên trong workspace.</td></tr><tr><td style="text-align:left;"><strong>Khách hàng Workspace</strong></td><td style="text-align:left;"><code>/workspaces/:id/clients</code></td><td style="text-align:left;">Ẩn danh sách khách hàng trong workspace.</td></tr></tbody></table><h3 id="_3-2-cau-hinh-menu-hien-thi-cho-ca-nhan-sidebar-menu-to-be" tabindex="-1">3.2. Cấu hình Menu hiển thị cho Cá nhân (Sidebar Menu To-Be) <a class="header-anchor" href="#_3-2-cau-hinh-menu-hien-thi-cho-ca-nhan-sidebar-menu-to-be" aria-label="Permalink to &quot;3.2. Cấu hình Menu hiển thị cho Cá nhân (Sidebar Menu To-Be)&quot;">​</a></h3><p>Sidebar dành cho Cá nhân chỉ giữ lại các tính năng cốt lõi phục vụ sản xuất và đăng tải:</p><ul><li>📊 <strong>Tổng quan</strong>: Dashboard làm việc, Báo cáo hiệu suất kênh (<code>/analytics</code>).</li><li>✍️ <strong>Sáng tạo &amp; Đăng bài</strong>: <ul><li>Viết bài mới (<code>/content-writing</code>)</li><li>Trình biên tập hình ảnh Canvas (<code>/editor</code>)</li><li>Mẫu nội dung (<code>/templates</code>)</li><li>Bộ thẻ hashtag (<code>/hashtag-groups</code>)</li><li>Lịch đăng bài (<code>/calendar</code>)</li><li>Thư viện đa phương tiện (<code>/library</code>)</li><li>Xuất bản &amp; Đăng bài (<code>/publish</code>)</li></ul></li><li>🔗 <strong>Kết nối &amp; Tài khoản</strong>: <ul><li>Kênh mạng xã hội (<code>/social-accounts</code>)</li><li>Cài đặt tài khoản &amp; Bảo mật (<code>/settings/profile</code>, <code>/settings/security</code>)</li><li>Trợ giúp &amp; Hướng dẫn (<code>/help/guide</code>)</li></ul></li></ul><hr><h2 id="_4-tinh-chinh-luong-duyet-bai-trong-trinh-viet-bai-content-writing-publishing" tabindex="-1">4. Tinh Chỉnh Luồng Duyệt Bài Trong Trình Viết Bài (Content Writing / Publishing) <a class="header-anchor" href="#_4-tinh-chinh-luong-duyet-bai-trong-trinh-viet-bai-content-writing-publishing" aria-label="Permalink to &quot;4. Tinh Chỉnh Luồng Duyệt Bài Trong Trình Viết Bài (Content Writing / Publishing)&quot;">​</a></h2><p>Trong giao diện <code>/content-writing</code>:</p><ul><li><strong>Chế độ Doanh nghiệp</strong>: Có nút <em>&quot;Gửi duyệt cho khách hàng&quot;</em> (Chuyển trạng thái sang <code>PENDING_CLIENT_APPROVAL</code>).</li><li><strong>Chế độ Cá nhân</strong>: <ul><li>Ẩn hoàn toàn nút <em>&quot;Gửi duyệt cho khách hàng&quot;</em>.</li><li>Thay thế bằng 2 nút hành động trực tiếp: <ol><li>🚀 <strong>&quot;Đăng ngay (Publish Now)&quot;</strong>: Gửi trực tiếp lên Fanpage/TikTok/Instagram đã kết nối.</li><li>⏰ <strong>&quot;Lên lịch đăng (Schedule)&quot;</strong>: Chọn ngày giờ xuất bản tự động vào lịch.</li></ol></li></ul></li></ul>`,23)])])}const p=n(o,[["render",h]]);export{u as __pageData,p as default};
